INSERT INTO regimes VALUES(2,'CHE','Xabi Alonso','알론소','2026-07-01',NULL,0,'레버쿠젠 3-4-2-1 블루프린트 이식 (docs/11). ⚠️ 25/26 첼시 팀 전술은 이 regime 것이 아니다');
INSERT INTO regimes VALUES(3,'LIV','Andoni Iraola','이라올라','2026-07-01',NULL,0,'본머스 실측 기반 이식 분석 (docs/12). ⚠️ 25/26 리버풀 팀 전술은 이 regime 것이 아니다');
INSERT INTO regimes VALUES(4,'ATM','Diego Simeone','시메오네','2011-12-23',NULL,0,'[2026-08-20] 확장 등록. ⭐⭐ **AVL·CHE·LIV와 결정적으로 다른 점: 재임 15년차라 팀 실측이 곧 감독 실측이다.** CHE(알론소)·LIV(이라올라)는 「25/26 팀 전술은 이 감독 것이 아니다」라는 경고가 붙지만 ATM은 그 경고가 필요 없다 — 2011-12-23 부임 이후 연속 재임이므로 **모든 시즌 실측이 시메오네 체제**다. ⇒ 이식 추론(projected) 없이 **measured 기반 정본**을 바로 쌓을 수 있는 유일한 비주(非主) 팀이다. 데이터 수집 시작점은 **26/27 라리가 1라운드**(사용자 지시).');
